/**
 * Tests whether the option can accept more arguments.
 *
 * @return false if the maximum number of arguments is reached.
 * @since 1.3
 */
boolean acceptsArg() {
    return (hasArg() || hasArgs() || hasOptionalArg()) && (argCount <= 0 || values.size() < argCount);
}
